import{validate,predictModel,wave}from './hidden-core.mjs';
const $=id=>document.getElementById(id);let result=null,worker=null,revealed=false,busy=false;
const fmt=n=>n.toExponential(2);
function configuration(){return validate({seed:+$('seed').value,samples:+$('samples').value,noise:+$('noise').value,steps:+$('steps').value,design:$('design').value});}
function draw(){const el=$('forecast'),r=el.getBoundingClientRect(),d=devicePixelRatio||1;el.width=r.width*d;el.height=r.height*d;const c=el.getContext('2d');c.scale(d,d);const w=r.width,h=r.height,x=z=>40+z*(w-55),y=z=>20+(1.2-z)/1.4*(h-55),t=+$('time').value/100;$('timeValue').value=`t = ${t.toFixed(2)}`;c.font='12px sans-serif';for(let i=0;i<=4;i++){const u=i/4;c.strokeStyle='#293746';c.beginPath();c.moveTo(x(0),y(u));c.lineTo(x(1),y(u));c.stroke();c.fillStyle='#a4b4c8';c.fillText(u.toFixed(2),3,y(u)+4);c.fillText(u.toFixed(2),x(u)-10,h-10);}c.fillText('Concentration u',40,12);if(!result){c.fillText('Run the comparison to train and fit the models.',45,h/2);return;}const line=(f,color,dash=[])=>{c.beginPath();c.setLineDash(dash);c.strokeStyle=color;c.lineWidth=2;for(let i=0;i<=160;i++){const X=i/160,Y=f(X);i?c.lineTo(x(X),y(Y)):c.moveTo(x(X),y(Y));}c.stroke();c.setLineDash([]);};c.save();c.beginPath();c.rect(40,20,w-55,h-55);c.clip();for(const[k,color]of[['nn','#ffb06b'],['pinn','#5ee4d0'],['classical','#b5a0fa']])line(X=>predictModel(result.model,k,X,t),color);if(revealed)line(X=>wave(X,t,result.truth.v,result.truth.D),'#d5dce5',[5,5]);c.restore();el.setAttribute('aria-label',`Concentration forecasts at time ${t}. Data-only RMSE ${fmt(result.metrics.nn.forecastRMSE)}, PINN ${fmt(result.metrics.pinn.forecastRMSE)}, conventional fit ${fmt(result.metrics.classical.forecastRMSE)}.`);}
function show(){const{model:m,fit:f,metrics:q}=result;$('results').hidden=false;$('measurements').hidden=false;$('observationRows').replaceChildren();for(const o of m.observations){const tr=document.createElement('tr');for(const n of [o.x,o.t,o.y]){const td=document.createElement('td');td.textContent=n.toFixed(5);tr.append(td);}$('observationRows').append(tr);}$('cards').replaceChildren();for(const[k,title]of[['nn','Data-only NN'],['pinn','Inverse PINN'],['classical','Conventional fit']]){const a=document.createElement('article');const p=k==='pinn'?m.parameters:k==='classical'?m.classical:null;a.innerHTML=`<h3>${title}</h3><small>FORECAST RMSE · t &gt; 0.4</small><strong>${fmt(q[k].forecastRMSE)}</strong><p>${p?`v = ${p.v.toFixed(4)}<br>D = ${p.D.toFixed(5)}`:'v, D: not estimated'}</p><p>Maximum mass error: ${fmt(q[k].massError)}</p><small>${f.nonIdentifiable&&p?'Parameters unsupported by these observations.':'Against exact mass 0.5 across evaluation times.'}</small>`;$('cards').append(a);}$('identifiability').textContent=f.nonIdentifiable?'Insufficient information: all observations are at t = 0. Every allowed speed and diffusion gives the same initial profile. Numerical estimates are arbitrary; more measurements at later times are required.':'Parameter estimates are conditional on the assumed transport equation, initial profile, and search bounds. Check sensitivity below; a fitted value alone does not establish uniqueness.';$('range').textContent=`Near-best conventional fits: v ∈ [${f.range.v.map(v=>v.toFixed(4)).join(', ')}], D ∈ [${f.range.D.map(v=>v.toFixed(5)).join(', ')}]. Threshold: best observation MSE ${fmt(f.mse)} + ${fmt(f.tolerance)}. Global grid: Δv = 0.025, ΔD = 0.001; local refinement: Δv = 0.0025, ΔD = 0.00025.`;draw();}
function setBusy(v){busy=v;for(const e of $('challenge').querySelectorAll('input,select'))e.disabled=v;$('run').disabled=v;$('stop').hidden=!v;$('download').disabled=v||!result;$('reveal').disabled=v||!result;}
function run(){const c=configuration();if(busy)return Promise.reject(Error('Training already running.'));result=null;revealed=false;$('results').hidden=true;$('measurements').hidden=true;$('truth').textContent='Hidden reference is revealed only after fitting.';$('reveal').textContent='Reveal reference';setBusy(true);draw();$('progress').max=c.steps;$('progress').value=0;$('status').textContent='Fitting observations and training both networks…';$('badge').textContent='Training';worker=new Worker('./hidden-worker.js',{type:'module'});return new Promise((resolve,reject)=>{const fail=message=>{worker.terminate();setBusy(false);$('status').textContent=message;$('badge').textContent='Stopped';reject(Error(message));};$('stop').onclick=()=>fail('Stopped. No completed model was saved.');worker.onerror=()=>fail('Could not run training. Reload and try again.');worker.onmessage=({data})=>{if(data.error){fail(data.error);return;}if(data.done){result=data;worker.terminate();setBusy(false);$('badge').textContent='Complete';$('status').textContent=`Completed ${c.steps} neural steps in ${data.elapsed.toFixed(1)} s (training and scoring). Results use seed ${c.seed}.`;show();resolve({parameters:data.model.parameters,metrics:data.metrics,nonIdentifiable:data.fit.nonIdentifiable});}else{$('progress').value=data.progress;$('status').textContent=`Training ${data.progress} / ${c.steps}. NN objective ${fmt(data.losses.nn)} · PINN objective ${fmt(data.losses.pinn)}.`;}};worker.postMessage(c);});}
$('challenge').onsubmit=e=>{e.preventDefault();run().catch(e=>{$('status').textContent=e.message;});};$('time').oninput=draw;$('reveal').onclick=()=>{revealed=!revealed;$('reveal').textContent=revealed?'Hide reference':'Reveal reference';$('truth').textContent=revealed?`Hidden truth: v = ${result.truth.v.toFixed(4)}, D = ${result.truth.D.toFixed(5)}. Dashed reference now visible.`:'Hidden reference is concealed.';draw();};$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(result.model,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`transport-model-seed-${result.model.config.seed}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};new ResizeObserver(draw).observe($('forecast').parentElement);for(const el of $('challenge').querySelectorAll('input,select'))el.addEventListener('change',()=>{if(result)$('status').textContent='Settings changed. Run again to apply; displayed results remain from the completed run.';});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'run_hidden_physics',title:'Run hidden physics challenge',description:'Train a data-only neural network and inverse PINN, fit a conventional transport model, and show held-out forecast errors.',inputSchema:{type:'object',properties:{seed:{type:'integer',minimum:1,maximum:9999},samples:{type:'integer',enum:[8,16,32,64]},noise:{type:'number',enum:[0,.01,.03]},steps:{type:'integer',enum:[1000,3000,6000]},design:{type:'string',enum:['spread','initial']}},required:['seed','samples','noise','steps','design'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async c=>{validate(c);if(busy)throw Error('Training already running.');for(const k of Object.keys(c))$(k).value=c[k];return run();}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>{lifecycle.abort();worker?.terminate();},{once:true});}
